//! Operator configuration, read from `/etc/archie/archie.toml`.
//!
//! # The trusted-substrate rule
//!
//! This file is written by a human or by the installer. It is **never** generated by a
//! model at boot. The specification is explicit that the trusted runtime substrate must
//! be deterministic, and that only the higher-level cognitive topology is dynamic — so
//! configuration is an input to the boot sequence, not an output of it.
//!
//! Every field has a defensible default. A node with no configuration file at all boots
//! as a `dev-vm` with a loopback fabric, which is safe: it holds no canonical state and
//! talks to nobody.

use archie_types::{Capability, ModuleId, NodeProfile};
use serde::{Deserialize, Serialize};
use std::net::SocketAddr;
use std::path::Path;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum ConfigError {
    #[error("cannot read {path}: {source}")]
    Io {
        path: String,
        #[source]
        source: std::io::Error,
    },

    #[error("{path} is not valid TOML: {source}")]
    Parse {
        path: String,
        #[source]
        source: toml::de::Error,
    },

    #[error("invalid configuration: {0}")]
    Invalid(String),
}

/// Which transport the fabric uses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "kebab-case")]
pub enum TransportKind {
    /// Real UDP over the network.
    Udp,
    /// In-process only. Discovers nothing; used for tests and isolated nodes.
    #[default]
    Loopback,
}

/// Where this machine physically is.
///
/// Operator-supplied and optional. There is no way to derive it: a hardware probe cannot
/// see out of the case, and the alternatives — geolocating an IP address, reading a
/// timezone — produce a confident answer that is wrong by a country. A globe that centres
/// on somewhere plausible is worse than one that centres on nothing, because the second
/// prompts the question and the first answers it incorrectly.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NodeLocation {
    pub latitude: f64,
    pub longitude: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct NodeSection {
    pub profile: NodeProfile,
    /// Capabilities the operator asserts beyond what hardware probing derives, e.g.
    /// `simulation.fea` because a solver is installed.
    pub extra_capabilities: Vec<String>,
    /// Where the machine is, when the operator has said. Absent means unknown, and the
    /// observatory makes no claim about a place rather than picking one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub location: Option<NodeLocation>,
}

impl Default for NodeSection {
    fn default() -> Self {
        Self {
            // A node that has not been told what it is must not be allowed to hold
            // canonical state.
            profile: NodeProfile::DevVm,
            extra_capabilities: Vec::new(),
            location: None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct FabricSection {
    pub transport: TransportKind,
    /// Address to bind when `transport = "udp"`.
    pub bind: String,
    /// Explicit peer addresses. Works where multicast is filtered, which is most
    /// networks worth deploying on.
    pub seeds: Vec<String>,
    /// IPv4 multicast group to join, if any.
    pub multicast_group: Option<String>,
    pub announce_interval_ms: i64,
    pub peer_timeout_ms: i64,
    pub peer_forget_ms: i64,
}

impl Default for FabricSection {
    fn default() -> Self {
        Self {
            transport: TransportKind::Loopback,
            bind: "0.0.0.0:7654".into(),
            seeds: Vec::new(),
            multicast_group: Some("239.255.42.1".into()),
            announce_interval_ms: 5_000,
            peer_timeout_ms: 20_000,
            peer_forget_ms: 3_600_000,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct SchedulerSection {
    pub slots_per_node: u32,
    pub reserved_active_slots: u32,
}

impl Default for SchedulerSection {
    fn default() -> Self {
        Self {
            slots_per_node: 4,
            reserved_active_slots: 1,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct PolicySection {
    /// Whether a verified physical safety boundary exists on this node.
    ///
    /// Defaults to `false`. Never default this to true: forgetting to configure it
    /// would then be indistinguishable from having configured it, and the difference
    /// is whether a motor can turn.
    pub safety_boundary_present: bool,
    pub max_lease_lifetime_ms: i64,
}

impl Default for PolicySection {
    fn default() -> Self {
        Self {
            safety_boundary_present: false,
            max_lease_lifetime_ms: 3_600_000,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(default, deny_unknown_fields)]
pub struct ModulesSection {
    /// Modules installed but explicitly turned off on this node.
    pub disabled: Vec<String>,
    /// Permissions the operator grants beyond the read-only defaults.
    pub grant_permissions: Vec<String>,
}

/// Which of the installed data-provider manifests this node may actually run.
///
/// Mirrors [`ModulesSection`] rather than inventing a second shape for the same idea:
/// a provider is turned off the same way a module is, and a capability *family* that
/// requires an explicit grant (`cyber`, today) is authorized the same way a module
/// permission is — both are the operator naming, in one file, every place this node is
/// allowed to reach outside itself.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(default, deny_unknown_fields)]
pub struct ProvidersSection {
    /// Provider ids installed but explicitly turned off on this node.
    pub disabled: Vec<String>,
    /// Capability families the operator has explicitly authorized — required before any
    /// provider in that family loads, whatever else is true about it. Empty means none:
    /// a node fresh out of the installer authorizes nothing it was not told to.
    pub authorized_families: Vec<String>,
}

/// Where the world data lives.
///
/// The globe's imagery is compiled into the display and needs nothing here. A vector map
/// is different: it is too large to ship, so it is fetched at install time to a path the
/// operator chose, and this is how the installed system is told where that was. Absent
/// means no vector map, which is the ordinary case and not a fault.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(default, deny_unknown_fields)]
pub struct WorldSection {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub map_data: Option<String>,
}

/// Conversation preferences, never proof of ownership or permission grants.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OwnerSection {
    pub name: String,
    pub nickname: String,
    pub address_as: String,
    pub ai_alias: String,
}

/// The whole configuration.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(default, deny_unknown_fields)]
pub struct ArchieConfig {
    pub node: NodeSection,
    pub fabric: FabricSection,
    pub scheduler: SchedulerSection,
    pub policy: PolicySection,
    pub modules: ModulesSection,
    pub providers: ProvidersSection,
    pub world: WorldSection,
    pub owner: Option<OwnerSection>,
}

impl ArchieConfig {
    /// Load from `path`, or return defaults if it does not exist.
    ///
    /// A *missing* file is fine; a *malformed* one is fatal. Booting with silently
    /// ignored configuration is how a node ends up in a state its operator did not ask
    /// for — including, potentially, one where a safety flag was meant to be set.
    pub fn load(path: impl AsRef<Path>) -> Result<Self, ConfigError> {
        let path = path.as_ref();
        if !path.exists() {
            return Ok(Self::default());
        }
        let text = std::fs::read_to_string(path).map_err(|source| ConfigError::Io {
            path: path.display().to_string(),
            source,
        })?;
        let config: Self = toml::from_str(&text).map_err(|source| ConfigError::Parse {
            path: path.display().to_string(),
            source,
        })?;
        config.validate()?;
        Ok(config)
    }

    /// Parse from a TOML string.
    pub fn from_toml(text: &str) -> Result<Self, ConfigError> {
        let config: Self = toml::from_str(text).map_err(|source| ConfigError::Parse {
            path: "<inline>".into(),
            source,
        })?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), ConfigError> {
        if let Some(owner) = &self.owner {
            for value in [
                &owner.name,
                &owner.nickname,
                &owner.address_as,
                &owner.ai_alias,
            ] {
                if value.trim().is_empty()
                    || value.chars().count() > 80
                    || value.chars().any(char::is_control)
                {
                    return Err(ConfigError::Invalid(
                        "owner preferences require 1..80 printable characters".into(),
                    ));
                }
            }
        }
        for name in &self.node.extra_capabilities {
            Capability::parse(name.clone())
                .map_err(|e| ConfigError::Invalid(format!("node.extra_capabilities: {e}")))?;
        }
        // A latitude outside the world is a typo, and wrapping it would silently move
        // the machine to another hemisphere. Longitude wraps legitimately — 181 east is
        // 179 west — but a value far outside the range is the same typo, so both are
        // refused rather than repaired.
        if let Some(location) = &self.node.location {
            if !location.latitude.is_finite() || !(-90.0..=90.0).contains(&location.latitude) {
                return Err(ConfigError::Invalid(format!(
                    "node.location.latitude {} is not a latitude",
                    location.latitude
                )));
            }
            if !location.longitude.is_finite() || !(-180.0..=180.0).contains(&location.longitude) {
                return Err(ConfigError::Invalid(format!(
                    "node.location.longitude {} is not a longitude",
                    location.longitude
                )));
            }
        }

        for name in &self.modules.disabled {
            ModuleId::parse(name.clone())
                .map_err(|e| ConfigError::Invalid(format!("modules.disabled: {e}")))?;
        }

        if self.fabric.transport == TransportKind::Udp {
            self.fabric.bind.parse::<SocketAddr>().map_err(|e| {
                ConfigError::Invalid(format!("fabric.bind {:?}: {e}", self.fabric.bind))
            })?;
            for seed in &self.fabric.seeds {
                seed.parse::<SocketAddr>()
                    .map_err(|e| ConfigError::Invalid(format!("fabric.seeds {seed:?}: {e}")))?;
            }
            if let Some(group) = &self.fabric.multicast_group {
                let addr: std::net::Ipv4Addr = group
                    .parse()
                    .map_err(|e| ConfigError::Invalid(format!("fabric.multicast_group: {e}")))?;
                if !addr.is_multicast() {
                    return Err(ConfigError::Invalid(format!(
                        "fabric.multicast_group {group} is not a multicast address"
                    )));
                }
            }
        }

        if self.fabric.announce_interval_ms <= 0 {
            return Err(ConfigError::Invalid(
                "fabric.announce_interval_ms must be positive".into(),
            ));
        }
        if self.fabric.peer_timeout_ms < self.fabric.announce_interval_ms * 2 {
            return Err(ConfigError::Invalid(
                "fabric.peer_timeout_ms must be at least twice the announce interval, or a \
                 single lost packet evicts a healthy peer"
                    .into(),
            ));
        }
        if self.fabric.peer_forget_ms < self.fabric.peer_timeout_ms {
            return Err(ConfigError::Invalid(
                "fabric.peer_forget_ms must not be shorter than fabric.peer_timeout_ms".into(),
            ));
        }

        if self.scheduler.slots_per_node == 0 {
            return Err(ConfigError::Invalid(
                "scheduler.slots_per_node must be at least 1".into(),
            ));
        }
        if self.scheduler.reserved_active_slots >= self.scheduler.slots_per_node {
            return Err(ConfigError::Invalid(
                "scheduler.reserved_active_slots must be less than slots_per_node, or no \
                 background work could ever run"
                    .into(),
            ));
        }
        if self.policy.max_lease_lifetime_ms <= 0 {
            return Err(ConfigError::Invalid(
                "policy.max_lease_lifetime_ms must be positive".into(),
            ));
        }
        Ok(())
    }

    /// Parsed extra capabilities. Safe to unwrap internally because [`Self::validate`]
    /// already rejected malformed names.
    pub fn extra_capabilities(&self) -> Vec<Capability> {
        self.node
            .extra_capabilities
            .iter()
            .filter_map(|name| Capability::parse(name.clone()).ok())
            .collect()
    }

    pub fn disabled_modules(&self) -> Vec<ModuleId> {
        self.modules
            .disabled
            .iter()
            .filter_map(|name| ModuleId::parse(name.clone()).ok())
            .collect()
    }

    /// Provider ids the operator has explicitly turned off.
    ///
    /// No parsed id type, unlike [`Self::disabled_modules`]: `ProviderManifest::id` is a
    /// plain dotted string in `archie-registry`, not a typed identifier, so there is
    /// nothing to parse into and filtering here would only silently drop a typo instead
    /// of leaving it to be reported as an id nothing matches.
    pub fn disabled_providers(&self) -> &[String] {
        &self.providers.disabled
    }

    /// Capability families the operator has explicitly authorized for data providers.
    pub fn authorized_provider_families(&self) -> &[String] {
        &self.providers.authorized_families
    }

    /// Seed addresses, parsed.
    pub fn seed_addresses(&self) -> Vec<SocketAddr> {
        self.fabric
            .seeds
            .iter()
            .filter_map(|s| s.parse().ok())
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_are_valid_and_safe() {
        let config = ArchieConfig::default();
        assert!(config.validate().is_ok());
        assert_eq!(config.node.profile, NodeProfile::DevVm);
        assert!(
            !config.policy.safety_boundary_present,
            "a node must never assume it has a safety boundary"
        );
        assert!(
            !config.node.profile.may_hold_canonical_state(),
            "an unconfigured node must not become the only copy of anything"
        );
    }

    #[test]
    fn a_missing_file_yields_defaults() {
        let missing = std::env::temp_dir().join("archie-no-such-config-xyz.toml");
        let _ = std::fs::remove_file(&missing);
        assert_eq!(
            ArchieConfig::load(&missing).unwrap(),
            ArchieConfig::default()
        );
    }

    #[test]
    fn a_malformed_file_is_fatal_not_ignored() {
        let path = std::env::temp_dir().join(format!("archie-bad-{}.toml", std::process::id()));
        std::fs::write(&path, "this is not = valid toml [[[").unwrap();
        // Silently falling back to defaults could quietly clear a safety flag.
        assert!(ArchieConfig::load(&path).is_err());
        std::fs::remove_file(&path).ok();
    }

    #[test]
    fn an_unknown_key_is_rejected() {
        // Catches typos like `safety_boundry_present`, which would otherwise be
        // silently ignored and leave the real flag at its default.
        let result = ArchieConfig::from_toml(
            r#"
[policy]
safety_boundry_present = true
"#,
        );
        assert!(result.is_err());
    }

    #[test]
    fn a_full_configuration_parses() {
        let config = ArchieConfig::from_toml(
            r#"
[node]
profile = "brain-node"
extra_capabilities = ["simulation.fea", "cad.parametric"]

[fabric]
transport = "udp"
bind = "0.0.0.0:7654"
seeds = ["10.0.0.5:7654", "10.0.0.6:7654"]
multicast_group = "239.255.42.1"
announce_interval_ms = 5000
peer_timeout_ms = 20000
peer_forget_ms = 600000

[scheduler]
slots_per_node = 8
reserved_active_slots = 2

[policy]
safety_boundary_present = false
max_lease_lifetime_ms = 900000

[modules]
disabled = ["devices.drone"]
"#,
        )
        .unwrap();

        assert_eq!(config.node.profile, NodeProfile::BrainNode);
        assert_eq!(config.extra_capabilities().len(), 2);
        assert_eq!(config.seed_addresses().len(), 2);
        assert_eq!(config.disabled_modules().len(), 1);
        assert_eq!(config.fabric.transport, TransportKind::Udp);
    }

    #[test]
    fn an_invalid_capability_name_is_rejected() {
        assert!(ArchieConfig::from_toml(
            r#"
[node]
extra_capabilities = ["Not A Capability"]
"#
        )
        .is_err());
    }

    #[test]
    fn a_bad_bind_address_is_rejected_only_for_udp() {
        assert!(ArchieConfig::from_toml(
            r#"
[fabric]
transport = "udp"
bind = "not-an-address"
"#
        )
        .is_err());

        // Loopback never binds, so the field is not checked.
        assert!(ArchieConfig::from_toml(
            r#"
[fabric]
transport = "loopback"
bind = "not-an-address"
"#
        )
        .is_ok());
    }

    #[test]
    fn a_non_multicast_group_is_rejected() {
        assert!(ArchieConfig::from_toml(
            r#"
[fabric]
transport = "udp"
multicast_group = "10.0.0.1"
"#
        )
        .is_err());
    }

    #[test]
    fn a_peer_timeout_shorter_than_two_announces_is_rejected() {
        assert!(ArchieConfig::from_toml(
            r#"
[fabric]
announce_interval_ms = 5000
peer_timeout_ms = 6000
"#
        )
        .is_err());
    }

    #[test]
    fn reserving_every_scheduler_slot_is_rejected() {
        assert!(ArchieConfig::from_toml(
            r#"
[scheduler]
slots_per_node = 2
reserved_active_slots = 2
"#
        )
        .is_err());
    }

    #[test]
    fn config_round_trips_through_toml() {
        let original = ArchieConfig::default();
        let text = toml::to_string(&original).unwrap();
        assert_eq!(ArchieConfig::from_toml(&text).unwrap(), original);
    }

    /// Where the machine is, when somebody has said.
    #[test]
    fn a_stated_location_is_read() {
        let config = ArchieConfig::from_toml(
            r#"
[node.location]
latitude = -33.4489
longitude = -70.6693
"#,
        )
        .expect("a location is configuration, not an error");
        let location = config.node.location.expect("it was stated");
        assert_eq!(location.latitude, -33.4489);
        assert_eq!(location.longitude, -70.6693);
    }

    /// And nothing is invented when nobody has.
    ///
    /// The absence has to survive as an absence. A default of (0, 0) would put every
    /// unconfigured node in the Gulf of Guinea and the display would draw it there with
    /// no way to tell that from a machine actually on that meridian.
    #[test]
    fn an_unstated_location_stays_unstated() {
        assert_eq!(ArchieConfig::default().node.location, None);
        assert_eq!(
            ArchieConfig::from_toml(
                "[node]
profile = \"server\"
"
            )
            .expect("valid")
            .node
            .location,
            None
        );
    }

    /// A latitude outside the world is a typo. Wrapping it would silently move the
    /// machine to the other hemisphere, which is worse than refusing the file.
    #[test]
    fn a_location_off_the_map_is_refused_rather_than_wrapped() {
        for bad in [
            "[node.location]
latitude = 91.0
longitude = 0.0
",
            "[node.location]
latitude = -90.5
longitude = 0.0
",
            "[node.location]
latitude = 0.0
longitude = 181.0
",
            "[node.location]
latitude = 0.0
longitude = -180.5
",
            "[node.location]
latitude = nan
longitude = 0.0
",
        ] {
            assert!(
                ArchieConfig::from_toml(bad).is_err(),
                "accepted a place that does not exist: {bad}"
            );
        }

        // The edges of the world are real places and stay accepted.
        for good in [
            "[node.location]
latitude = 90.0
longitude = 180.0
",
            "[node.location]
latitude = -90.0
longitude = -180.0
",
        ] {
            assert!(ArchieConfig::from_toml(good).is_ok(), "{good}");
        }
    }

    /// Half a coordinate is not a location.
    #[test]
    fn a_location_missing_half_of_itself_is_refused() {
        assert!(ArchieConfig::from_toml(
            "[node.location]
latitude = 10.0
"
        )
        .is_err());
        assert!(ArchieConfig::from_toml(
            "[node.location]
longitude = 10.0
"
        )
        .is_err());
    }
}
